type Пользователь = { имя: string; возраст: number; город: string };

function обновить(текущий: Пользователь, изменения: Partial<Пользователь>): Пользователь {
  return { ...текущий, ...изменения };
}
console.log(обновить({ имя: "Анна", возраст: 25, город: "Омск" }, { возраст: 26 }));
